{"command": "python3 - <<'PY'
import glob,json,re,collections,os
# cross-check filename vs tag/service, error message breakdown
mismatch=[]; errmsg=collections.Counter(); users=collections.Counter(); warn_lines=0
for fn in glob.glob('logs/*'):
    base=os.path.basename(fn).rsplit('-',1)[0]
    ext=os.path.splitext(fn)[1]
    for i,line in enumerate(open(fn),1):
        line=line.rstrip('\n')
        if not line: continue
        if ext=='.jsonl':
            d=json.loads(line); svc=d['service']; level=d['level']; msg=d['msg']
        else:
            m=re.match(r'^(\S+)\s+(\w+)\s+\[([^\]]+)\]\s+(.*)$',line); ts,level,svc,msg=m.groups()
        if svc!=base: mismatch.append((fn,i,svc,base))
        if level=='ERROR':
            p=re.sub(r'\d+','N',msg); errmsg[(svc,p)]+=1
        if svc=='auth' and level=='WARN' and 'login failed' in msg:
            warn_lines+=1
            users[msg.split('user=')[1].strip()]+=1
print('mismatch',mismatch[:5],len(mismatch))
print('warn_lines',warn_lines,'users',users)
for k,v in sorted(errmsg.items()): print(k,v)
PY", "description": "Cross-check service tags and error message breakdown"}

